mapper.update:
UPDATE #{schema}.ecos_scenario_canvas_layout
SET layout_json = #{row.layoutJson},
    layout_version = layout_version + 1,
    version_no = version_no + 1,
    update_by = #{row.updateBy},
    update_time = NOW()
WHERE id = #{row.id}
  AND scenario_id = #{row.scenarioId}
  AND layout_version = #{row.expectedVersion}
  AND is_deleted = 0
